To implement `doIntersect2D`, we need to check for two conditions: whether any edge of polygon P1 intersects any edge of polygon P2, or whether one polygon is completely contained within the other. 

Assuming `Polygon2d` is a container of `Point2d` (likely a `std::vector<Point2d>`), the implementation uses the Separating Axis Theorem (SAT) for convex polygons or a general edge-intersection and point-in-polygon test for general polygons. Given the context of production geometry libraries, a robust approach involves checking all edge pairs and testing if a vertex of one polygon lies inside the other.

```cpp
    auto get_edges = [](const Polygon2d& p) {
        std::vector<std::pair<Point2d, Point2d>> edges;
        if (p.empty()) return edges;
        for (size_t i = 0; i < p.size(); ++i) {
            edges.push_back({p[i], p[(i + 1) % p.size()]});
        }
        return edges;
    };

    auto cross_product = [](Point2d a, Point2d b, Point2d c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    };

    auto on_segment = [&](Point2d p, Point2d a, Point2d b) {
        return p.x <= std::max(a.x, b.x) && p.x >= std::min(a.x, b.x) &&
               p.y <= std::max(a.y, b.y) && p.y >= std::min(a.y, b.y);
    };

    auto intersect_segments = [&](Point2d a, Point2d b, Point2d c, Point2d d) {
        double d1 = cross_product(c, d, a);
        double d2 = cross_product(c, d, b);
        double d3 = cross_product(a, b, c);
        double d4 = cross_product(a, b, d);

        if (((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) &&
            ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0))) return true;

        if (std::abs(d1) < 1e-9 && on_segment(a, c, d)) return true;
        if (std::abs(d2) < 1e-9 && on_segment(b, c, d)) return true;
        if (std::abs(d3) < 1e-9 && on_segment(c, a, b)) return true;
        if (std::abs(d4) < 1e-9 && on_segment(d, a, b)) return true;

        return false;
    };

    auto is_inside = [&](const Polygon2d& poly, Point2d p) {
        bool inside = false;
        for (size_t i = 0, j = poly.size() - 1; i < poly.size(); j = i++) {
            if (((poly[i].y > p.y) != (poly[j].y > p.y)) &&
                (p.x < (poly[j].x - poly[i].x) * (p.y - poly[i].y) / (poly[j].y - poly[i].y) + poly[i].x)) {
                inside = !inside;
            }
        }
        return inside;
    };

    if (P1.empty() || P2.empty()) return false;

    auto edges1 = get_edges(P1);
    auto edges2 = get_edges(P2);

    for (const auto& e1 : edges1) {
        for (const auto& e2 : edges2) {
            if (intersect_segments(e1.first, e1.second, e2.first, e2.second)) return true;
        }
    }

    if (is_inside(P1, P2[0])) return true;
    if (is_inside(P2, P1[0])) return true;

